use clap::Parser;
use std::fs::{self, File};
use std::io::Read;
use std::path::PathBuf;
use std::sync::{Arc, Mutex};
use std::time::Instant;
use rayon::prelude::*;
use itertools::Itertools;

#[derive(Parser, Debug)]
#[command(about = "Find the password of protected ZIP files", long_about = None)]
struct Args {
    #[arg(short, long, help = "path to zip input file")]
    inputFile: PathBuf,

    #[arg(short, long, help = "number of workers")]
    workers: Option<usize>,

    #[arg(short, long, help = "path to a password dictionary file")]
    passwordDictionary: Option<PathBuf>,

    #[arg(short, long, help = "charset to use to generate password", default_value = "lud")]
    charset: Option<String>,

    #[arg(long, help = "path to a charset file")]
    charsetFile: Option<PathBuf>,

    #[arg(long, help = "minimum password length", default_value = "1")]
    minPasswordLen: usize,

    #[arg(long, help = "maximum password length", default_value = "10")]
    maxPasswordLen: usize,

    #[arg(long, help = "file number in the zip archive", default_value = "0")]
    fileNumber: usize,

    #[arg(short, long, help = "password to start from")]
    startingPassword: Option<String>,

    #[arg(short, long, action = clap::ArgAction::Version)]
    version: Option<bool>,
}

fn get_charset(charset_str: &str, charset_file: Option<PathBuf>) -> Result<String, String> {
    if let Some(file_path) = charset_file {
        match fs::read_to_string(&file_path) {
            Ok(content) => Ok(content.trim().to_string()),
            Err(_) => Err(format!("Failed to read charset file: {:?}", file_path)),
        }
    } else {
        let mut result = String::new();
        for c in charset_str.chars() {
            match c {
                'l' => result.push_str("abcdefghijklmnopqrstuvwxyz"),
                'u' => result.push_str("ABCDEFGHIJKLMNOPQRSTUVWXYZ"),
                'd' => result.push_str("0123456789"),
                'h' => result.push_str("0123456789abcdef"),
                'H' => result.push_str("0123456789ABCDEF"),
                's' => result.push_str(" !\"#$%&'()*+,-./:;<=>?@[\\]^_`{|}~"),
                _ => return Err(format!("Unknown charset character: {}", c)),
            }
        }
        Ok(result)
    }
}

fn try_password(zip_path: &PathBuf, password: &str, file_number: usize) -> bool {
    if let Ok(file) = File::open(zip_path) {
        if let Ok(mut archive) = zip::ZipArchive::new(file) {
            if file_number >= archive.len() {
                return false;
            }
            if let Ok(mut file_in_zip) = archive.by_index_decrypt(file_number, password.as_bytes()) {
                if let Ok(_) = file_in_zip {
                    return true;
                }
            }
        }
    }
    false
}

fn load_dictionary(dict_path: &PathBuf) -> Result<Vec<String>, String> {
    match fs::read_to_string(dict_path) {
        Ok(content) => {
            Ok(content
                .lines()
                .map(|line| line.to_string())
                .collect())
        }
        Err(_) => Err(format!("Failed to read dictionary file: {:?}", dict_path)),
    }
}

fn generate_passwords(
    charset: &str,
    min_len: usize,
    max_len: usize,
    starting_password: Option<String>,
) -> Vec<String> {
    let mut passwords = Vec::new();

    for len in min_len..=max_len {
        for combo in (0..charset.len()).combinations_with_replacement(len) {
            let password: String = combo.iter().map(|&i| charset.chars().nth(i).unwrap()).collect();

            if let Some(ref start) = starting_password {
                if password < *start {
                    continue;
                }
            }

            passwords.push(password);
        }
    }

    passwords
}

fn main() {
    let args = Args::parse();

    // Validate input file exists
    if !args.inputFile.exists() {
        eprintln!("CLI argument error - \"'inputFile' does not exist\"");
        std::process::exit(1);
    }

    let start_time = Instant::now();
    let found = Arc::new(Mutex::new(None::<String>));

    // Determine passwords to try
    let passwords = if let Some(dict_path) = &args.passwordDictionary {
        match load_dictionary(dict_path) {
            Ok(dict) => dict,
            Err(e) => {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        let charset_str = if let Some(charset_file) = &args.charsetFile {
            match get_charset("", Some(charset_file.clone())) {
                Ok(c) => c,
                Err(e) => {
                    eprintln!("Error: {}", e);
                    std::process::exit(1);
                }
            }
        } else {
            match get_charset(&args.charset.as_ref().unwrap_or(&"lud".to_string()), None) {
                Ok(c) => c,
                Err(e) => {
                    eprintln!("Error: {}", e);
                    std::process::exit(1);
                }
            }
        };

        generate_passwords(
            &charset_str,
            args.minPasswordLen,
            args.maxPasswordLen,
            args.startingPassword.clone(),
        )
    };

    // Set up thread pool
    if let Some(num_workers) = args.workers {
        rayon::ThreadPoolBuilder::new()
            .num_threads(num_workers)
            .build()
            .unwrap()
            .install(|| {
                let found = found.clone();
                let zip_path = args.inputFile.clone();
                let file_number = args.fileNumber;

                passwords.par_iter().for_each(|password| {
                    let mut f = found.lock().unwrap();
                    if f.is_some() {
                        return;
                    }
                    drop(f);

                    if try_password(&zip_path, password, file_number) {
                        let mut f = found.lock().unwrap();
                        if f.is_none() {
                            *f = Some(password.clone());
                        }
                    }
                });
            });
    } else {
        let found = found.clone();
        let zip_path = args.inputFile.clone();
        let file_number = args.fileNumber;

        passwords.par_iter().for_each(|password| {
            let mut f = found.lock().unwrap();
            if f.is_some() {
                return;
            }
            drop(f);

            if try_password(&zip_path, password, file_number) {
                let mut f = found.lock().unwrap();
                if f.is_none() {
                    *f = Some(password.clone());
                }
            }
        });
    }

    let elapsed = start_time.elapsed();
    let nanos = elapsed.subsec_nanos();
    let micros = nanos / 1000;
    let remaining_nanos = nanos % 1000;

    println!(
        "Time elapsed: {}ms {}us {}ns",
        elapsed.as_millis(),
        micros,
        remaining_nanos
    );

    if let Some(password) = found.lock().unwrap().as_ref() {
        println!("Password found:{}", password);
    } else {
        println!("Password not found");
    }
}
