fn try_password(zip_path: &PathBuf, password: &str, file_number: usize) -> bool {
    // Try to open and check the password on the ZIP file
    // We'll use a simple approach - try to read the local header
    if let Ok(mut file) = File::open(zip_path) {
        // Read the ZIP file and find the file entry
        if let Ok(data) = read_zip_file(&mut file, file_number, password) {
