fn validate_zip_password(data: &[u8], password: &str) -> bool {
    if data.len() < 12 {
        return false;
    }

    // Initialize CRC32 table and keys
    let mut crc_table = [0u32; 256];
    for i in 0..256 {
        let mut crc = i as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xedb88320;
            } else {
                crc >>= 1;
            }
        }
        crc_table[i] = crc;
    }

    // Initialize keys
    let mut key0 = 0x12345678u32;
    let mut key1 = 0x23456789u32;
    let mut key2 = 0x34567890u32;

