fn update_keys(key0: &mut u32, key1: &mut u32, key2: &mut u32, byte: u8, crc_table: &[u32; 256]) {
    *key0 = (*key0 ^ byte as u32).wrapping_mul(134775813).wrapping_add(1);
    *key1 = (*key1).wrapping_add((*key0 >> 24) as u32);
    *key1 = (*key1).wrapping_mul(134775813).wrapping_add(1);
    let temp = (*key1 >> 24) as u8;
    *key2 = (*key2 ^ (temp as u32)).wrapping_mul(134775813).wrapping_add(1);
}

fn decrypt_byte(key2: u32) -> u8 {
    let temp = key2 as u16 | 2;
    (((temp * (temp ^ 1)) >> 8) & 0xff) as u8
}

fn load_dictionary(dict_path: &PathBuf) -> Result<Vec<String>, String> {
    match fs::read_to_string(dict_path) {
        Ok(content) => {
            Ok(content
                .lines()
                .map(|line| line.to_string())
                .collect())
        }
        Err(_) => Err(format!("Failed to read dictionary file: {:?}", dict_path)),
    }
}

fn generate_passwords(
    charset: &str,
    min_len: usize,
    max_len: usize,
    starting_password: Option<String>,
) -> Vec<String> {
    let mut passwords = Vec::new();
    let charset_vec: Vec<char> = charset.chars().collect();

    fn generate_recursive(
        charset_vec: &[char],
        current: String,
        target_len: usize,
        passwords: &mut Vec<String>,
        starting_password: &Option<String>,
    ) {
        if current.len() == target_len {
            if let Some(ref start) = starting_password {
                if current >= *start {
                    passwords.push(current);
                }
            } else {
                passwords.push(current);
            }
            return;
        }

        for &c in charset_vec {
            let mut new_password = current.clone();
            new_password.push(c);
            generate_recursive(charset_vec, new_password, target_len, passwords, starting_password);
        }
    }

    for len in min_len..=max_len {
        generate_recursive(&charset_vec, String::new(), len, &mut passwords, &starting_password);
    }

    passwords
}

