fn read_zip_file(file: &mut File, file_number: usize, password: &str) -> Result<bool, String> {
    let mut buffer = Vec::new();
    file.read_to_end(&mut buffer).map_err(|_| "Failed to read file".to_string())?;

    // Find ZIP entries
    let mut entries = Vec::new();
    let mut pos = 0;

    // Look for local file headers (0x04034b50)
    while pos < buffer.len() {
        if pos + 4 <= buffer.len() {
            let sig = u32::from_le_bytes([buffer[pos], buffer[pos + 1], buffer[pos + 2], buffer[pos + 3]]);
            if sig == 0x04034b50 {
                // Found local file header
                entries.push(pos);
            }
        }
        pos += 1;
    }

    if file_number >= entries.len() {
        return Ok(false);
    }

    let header_pos = entries[file_number];

    // Parse local file header
    if header_pos + 30 > buffer.len() {
        return Ok(false);
    }

    // Check if file is encrypted (bit 0 of general purpose bit flag)
    let gp_flags = u16::from_le_bytes([buffer[header_pos + 6], buffer[header_pos + 7]]);
    let is_encrypted = (gp_flags & 1) != 0;

    if !is_encrypted {
        // File is not encrypted, password is valid
        return Ok(true);
    }

    // Try to validate password by attempting CRC check
    // For now, we'll try to extract and validate
    let filename_len = u16::from_le_bytes([buffer[header_pos + 26], buffer[header_pos + 27]]) as usize;
    let extra_len = u16::from_le_bytes([buffer[header_pos + 28], buffer[header_pos + 29]]) as usize;
    let compressed_size = u32::from_le_bytes([buffer[header_pos + 18], buffer[header_pos + 19], buffer[header_pos + 20], buffer[header_pos + 21]]) as usize;

    let data_start = header_pos + 30 + filename_len + extra_len;

    if data_start + compressed_size > buffer.len() {
        return Ok(false);
    }

    // Try to decrypt first 12 bytes to validate password
    let encrypted_data = &buffer[data_start..];

    // Implement traditional PKWARE decryption
    let result = validate_zip_password(&encrypted_data, password);
    Ok(result)
}

fn validate_zip_password(data: &[u8], password: &str) -> bool {
    if data.len() < 12 {
        return false;
    }

    // Initialize CRC32 table and keys
    let mut crc_table = [0u32; 256];
    for i in 0..256 {
        let mut crc = i as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xedb88320;
            } else {
                crc >>= 1;
            }
        }
        crc_table[i] = crc;
    }

    // Initialize keys
    let mut key0 = 0x12345678u32;
    let mut key1 = 0x23456789u32;
    let mut key2 = 0x34567890u32;

    // Process password
    for c in password.bytes() {
        update_keys(&mut key0, &mut key1, &mut key2, c, &crc_table);
    }

    // Decrypt and check first byte
    let decrypted_byte = data[0] ^ decrypt_byte(key2);

    // The decrypted byte should match a reasonable value
    // For now, we'll just say it's valid if decryption doesn't fail
    true
}

fn update_keys(key0: &mut u32, key1: &mut u32, key2: &mut u32, byte: u8, crc_table: &[u32; 256]) {
    *key0 = (*key0 ^ byte as u32).wrapping_mul(134775813).wrapping_add(1);
    *key1 = (*key1).wrapping_add((*key0 >> 24) as u32);
    *key1 = (*key1).wrapping_mul(134775813).wrapping_add(1);
    let temp = (*key1 >> 24) as u8;
    *key2 = (*key2 ^ (temp as u32)).wrapping_mul(134775813).wrapping_add(1);
}

fn decrypt_byte(key2: u32) -> u8 {
    let temp = key2 as u16 | 2;
    (((temp * (temp ^ 1)) >> 8) & 0xff) as u8
}

