// CRC32 computation
fn compute_crc32(data: &[u8]) -> u32 {
    let mut crc_table = [0u32; 256];
    for i in 0..256 {
        let mut crc = i as u32;
        for _ in 0..8 {
            if crc & 1 != 0 {
                crc = (crc >> 1) ^ 0xedb88320;
            } else {
                crc >>= 1;
            }
        }
        crc_table[i] = crc;
    }

    let mut crc = 0xffffffff_u32;
    for &byte in data {
        crc = (crc >> 8) ^ crc_table[((crc ^ byte as u32) & 0xff) as usize];
    }
    crc ^ 0xffffffff
