// PKWARE traditional encryption
struct ZipCrypto {
    key0: u32,
    key1: u32,
    key2: u32,
    crc_table: [u32; 256],
}

impl ZipCrypto {
    fn new() -> Self {
        let mut crc_table = [0u32; 256];
        for i in 0..256 {
            let mut crc = i as u32;
            for _ in 0..8 {
                if crc & 1 != 0 {
                    crc = (crc >> 1) ^ 0xedb88320;
                } else {
                    crc >>= 1;
                }
            }
            crc_table[i] = crc;
        }

        ZipCrypto {
            key0: 0x12345678,
            key1: 0x23456789,
            key2: 0x34567890,
            crc_table,
        }
    }

    fn init_keys(&mut self, password: &[u8]) {
        self.key0 = 0x12345678;
        self.key1 = 0x23456789;
        self.key2 = 0x34567890;

        for &byte in password {
            self.update_keys(byte);
        }
    }

    fn update_keys(&mut self, byte: u8) {
        self.key0 = (self.key0 ^ byte as u32).wrapping_mul(134775813).wrapping_add(1);
        self.key1 = self.key1.wrapping_add(self.key0 >> 24);
        self.key1 = self.key1.wrapping_mul(134775813).wrapping_add(1);
        let temp = (self.key1 >> 24) as u8;
        self.key2 = (self.key2 ^ temp as u32).wrapping_mul(134775813).wrapping_add(1);
    }

    fn decrypt_byte(&self) -> u8 {
        let temp = self.key2 as u16 | 2;
        (((temp * (temp ^ 1)) >> 8) & 0xff) as u8
    }

    fn decrypt(&mut self, data: &[u8]) -> Vec<u8> {
        let mut result = Vec::new();
        for &byte in data {
            let key_byte = self.decrypt_byte();
            result.push(byte ^ key_byte);
            self.update_keys(result[result.len() - 1]);
        }
        result
    }
}

