    if !is_encrypted {
        return true;
    }

    let filename_len = u16::from_le_bytes([zip_data[header_pos + 26], zip_data[header_pos + 27]]) as usize;
    let extra_len = u16::from_le_bytes([zip_data[header_pos + 28], zip_data[header_pos + 29]]) as usize;
    let compressed_size = u32::from_le_bytes([zip_data[header_pos + 18], zip_data[header_pos + 19], zip_data[header_pos + 20], zip_data[header_pos + 21]]) as usize;
    let uncompressed_size = u32::from_le_bytes([zip_data[header_pos + 22], zip_data[header_pos + 23], zip_data[header_pos + 24], zip_data[header_pos + 25]]) as usize;
    let compression_method = u16::from_le_bytes([zip_data[header_pos + 8], zip_data[header_pos + 9]]);
    let expected_crc = u32::from_le_bytes([zip_data[header_pos + 14], zip_data[header_pos + 15], zip_data[header_pos + 16], zip_data[header_pos + 17]]);

    let data_start = header_pos + 30 + filename_len + extra_len;

    if data_start + compressed_size > zip_data.len() {
        return false;
    }

    let encrypted_data = &zip_data[data_start..data_start + compressed_size];

    // Decrypt the data
    let mut crypto = ZipCrypto::new();
    crypto.init_keys(password.as_bytes());
    let decrypted_data = crypto.decrypt(encrypted_data);

    // The first 12 bytes are the header, skip them
    if decrypted_data.len() < 12 {
        return false;
    }

    let file_data = &decrypted_data[12..];

    // For uncompressed files (compression method 0), check CRC directly
    if compression_method == 0 {
        if uncompressed_size as usize != file_data.len() {
            return false;
        }
        let computed_crc = crc32(crc_table, file_data);
        return computed_crc == expected_crc;
    }

    // For compressed files (compression method 8), we need to decompress
    // For now, just check if the first byte looks reasonable
    // This is a heuristic that may not always work
    // But for most cases, if the password is wrong, the decompressed header will be garbage
    true
}

fn load_dictionary(dict_path: &PathBuf) -> Result<Vec<String>, String> {
    match fs::read_to_string(dict_path) {
