        starting_password: &Option<String>,
    ) {
        if current.len() == target_len {
            if let Some(ref start) = starting_password {
                if current >= *start {
                    passwords.push(current);
                }
            } else {
                passwords.push(current);
            }
            return;
        }

        for &c in charset_vec {
            let mut new_password = current.clone();
            new_password.push(c);
            generate_recursive(charset_vec, new_password, target_len, passwords, starting_password);
        }
    }

    for len in min_len..=max_len {
        generate_recursive(&charset_vec, String::new(), len, &mut passwords, &starting_password);
    }

    passwords
}

fn main() {
    let args = match parse_args() {
        Ok(a) => a,
        Err(e) => {
            eprintln!("Error: {}", e);
            std::process::exit(1);
        }
    };

    if args.help {
        print_help();
        return;
    }

    if args.version {
        println!("zip-password-finder 0.10.3");
        return;
    }

    // Validate input file exists
    if args.inputFile.as_os_str().is_empty() || !args.inputFile.exists() {
        eprintln!("CLI argument error - \"'inputFile' does not exist\"");
        std::process::exit(1);
    }

    // Read the ZIP file
    let mut zip_file = match File::open(&args.inputFile) {
        Ok(f) => f,
        Err(_) => {
            eprintln!("Failed to open ZIP file");
            std::process::exit(1);
        }
    };

    let mut zip_data = Vec::new();
    if let Err(_) = zip_file.read_to_end(&mut zip_data) {
        eprintln!("Failed to read ZIP file");
        std::process::exit(1);
    }

    let start_time = Instant::now();
    let found = Arc::new(Mutex::new(None::<String>));
    let crc_table = make_crc_table();

    // Determine passwords to try
    let passwords = if let Some(dict_path) = &args.passwordDictionary {
        match load_dictionary(dict_path) {
            Ok(dict) => dict,
            Err(e) => {
                eprintln!("Error: {}", e);
                std::process::exit(1);
            }
        }
    } else {
        let charset_str = if let Some(charset_file) = &args.charsetFile {
            match get_charset("", Some(charset_file.clone())) {
                Ok(c) => c,
                Err(e) => {
                    eprintln!("Error: {}", e);
                    std::process::exit(1);
                }
            }
        } else {
            match get_charset(&args.charset, None) {
                Ok(c) => c,
                Err(e) => {
                    eprintln!("Error: {}", e);
                    std::process::exit(1);
                }
            }
        };

        generate_passwords(
            &charset_str,
            args.minPasswordLen,
            args.maxPasswordLen,
            args.startingPassword.clone(),
        )
    };

    // Try passwords
    let file_number = args.fileNumber;

    for password in passwords {
        {
            let f = found.lock().unwrap();
            if f.is_some() {
                break;
            }
        }

        if try_password(&zip_data, file_number, &password, &crc_table) {
            let mut f = found.lock().unwrap();
            if f.is_none() {
                *f = Some(password);
            }
            break;
        }
    }

    let elapsed = start_time.elapsed();
    let nanos = elapsed.subsec_nanos();
    let micros = nanos / 1000;
    let remaining_nanos = nanos % 1000;

    println!(
        "Time elapsed: {}ms {}us {}ns",
        elapsed.as_millis(),
        micros,
        remaining_nanos
    );

    {
        let f = found.lock().unwrap();
        if let Some(password) = f.as_ref() {
            println!("Password found:{}", password);
        } else {
            println!("Password not found");
        }
    }
}
